fn count7(x: u8) -> u8 {
    // Initialize a counter for the number of 7s
    let mut count = 0;
    let mut num = x;

    // Loop until num is 0
    while num > 0 {
        // Check if the last digit is 7
        if num % 10 == 7 {
            count += 1;
        }
        // Remove the last digit
        num /= 10;
    }

    count
}

